/// changelog-feed: Changelog with RSS
private struct ChangelogFeedExample0: View {
    @Environment(\.monarchTheme) private var theme

    private struct ReleaseTag: Hashable {
        let label: String
        var tone: MonarchTone = .neutral
    }

    private struct Release: Identifiable {
        let id: String
        let date: Date
        let version: String?
        let title: String
        let tags: [ReleaseTag]
        let notes: String?
        let url: URL?
    }

    private let releases = [
        Release(
            id: "sample-export",
            date: Date(timeIntervalSince1970: 1_780_272_000),
            version: "2.4.0",
            title: "Reports can be exported",
            tags: [ReleaseTag(label: "New", tone: .accent), ReleaseTag(label: "Reports")],
            notes: "Every report now has an Export button. Files keep the filters you applied.",
            url: URL(string: "#sample-export")
        ),
        Release(
            id: "sample-search",
            date: Date(timeIntervalSince1970: 1_779_235_200),
            version: nil,
            title: "Search remembers your last query",
            tags: [ReleaseTag(label: "Improved")],
            notes: "Opening search again shows the last query and its results.",
            url: nil
        ),
        Release(
            id: "sample-fix",
            date: Date(timeIntervalSince1970: 1_778_544_000),
            version: nil,
            title: "Fixed a sorting issue in tables",
            tags: [ReleaseTag(label: "Fix")],
            notes: nil,
            url: nil
        ),
    ]

    private func dateLine(_ release: Release) -> String {
        let utc = TimeZone(identifier: "UTC") ?? .current
        let style = Date.FormatStyle(date: .long, time: .omitted, locale: Locale(identifier: "en-GB"), timeZone: utc)
        return release.date.formatted(style) + (release.version.map { " \u{00B7} " + $0 } ?? "")
    }

    var body: some View {
        NavigationStack {
            List {
                Section {
                    ForEach(releases) { release in
                HStack(alignment: .top, spacing: theme.spacing.space3) {
                Circle()
                    .strokeBorder(theme.colors.accentSolid, lineWidth: 2)
                    .frame(width: 12, height: 12)
                    .padding(.top, 3)
                    .accessibilityHidden(true)
                VStack(alignment: .leading, spacing: theme.spacing.space2) {
                    Text(dateLine(release))
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                    Text(release.title)
                        .monarchTextStyle(.subheading)
                        .accessibilityAddTraits(.isHeader)
                    MonarchFlowLayout {
                        ForEach(release.tags, id: \.self) { tag in
                            MonarchBadge(tag.label, tone: tag.tone)
                        }
                    }
                    if let notes = release.notes {
                        MonarchProse(MonarchProseStyle(size: .sm, limitsLineLength: false)) {
                            Text(MonarchProseStyle(size: .sm).markdown(notes, in: theme))
                        }
                    }
                    if let url = release.url {
                        Link("Read more", destination: url)
                            .buttonStyle(.monarchLink(.standalone, isExternal: true))
                    }
                }
                }
                .padding(.vertical, theme.spacing.space2)
                    }
                } header: {
                    VStack(alignment: .leading, spacing: theme.spacing.space2) {
                        Text("Sample entries showing the layout.")
                        Label("RSS feed", systemImage: "dot.radiowaves.up.forward")
                            .foregroundStyle(theme.colors.textLink)
                    }
                }
            }
            .listStyle(.plain)
            .monarchCanvas()
            .navigationTitle("Changelog")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
        }
        .frame(minHeight: theme.spacing.space24 * 5)
    }
}

