    @State private var status = MonarchSaveStatus.idle

    private func choiceCard(_ title: String, symbol: String, value: Int) -> some View {
        let isOn = rating == value
        return Button {
            rating = isOn ? nil : value
            if !isOn { save() }
        } label: {
            VStack(spacing: theme.spacing.space2) {
                Image(systemName: symbol)
                Text(title).monarchTextStyle(.label)
            }
            .foregroundStyle(isOn ? theme.colors.accentStrong : theme.colors.textDefault)
            .frame(maxWidth: .infinity, minHeight: 72)
            .background(
                isOn ? theme.colors.accentSubtle : Color.clear,
                in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous)
            )
            .overlay(
                RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous)
                    .strokeBorder(isOn ? theme.colors.accentBorder : theme.colors.borderDefault, lineWidth: 1.5)
            )
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(isOn ? .isSelected : [])
    }

    private func save() {
        status = .saving
        Task {
            // Send the rating and comment to the server here.
            try? await Task.sleep(for: .milliseconds(200))
            status = .saved
        }
    }

    var body: some View {
        VStack(spacing: theme.spacing.space4) {
            Text("Request #1042 · Billing question")
                .monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
            Text("How would you rate the support you received?")
                .monarchTextStyle(.heading)
                .multilineTextAlignment(.center)
                .accessibilityAddTraits(.isHeader)
            HStack(spacing: theme.spacing.space3) {
                choiceCard("Good", symbol: "hand.thumbsup", value: 2)
                choiceCard("Bad", symbol: "hand.thumbsdown", value: 1)
            }
            if rating == nil {
                Text("Choose an answer above. You can add a comment afterwards.")
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                    .multilineTextAlignment(.center)
            } else {
                MonarchFormField("Anything you’d like to add?", helper: "\(500 - comment.count) characters left") {
                    TextField("Comment", text: $comment, axis: .vertical)
                        .lineLimit(3...6)
                        .textFieldStyle(.roundedBorder)
                }
                HStack {
                    MonarchButton("Save comment", isLoading: status == .saving) { save() }
                        .disabled(comment.isEmpty)
                    MonarchSaveStatusIndicator(status) { save() }
                }
            }
        }
        .padding(theme.spacing.space4)
        .frame(maxWidth: .infinity)
        .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous)
                .strokeBorder(theme.colors.borderSubtle)
        )
    }
}

