    private let source = [
        MonarchNotificationCenterItem(
            id: "n1",
            title: "Ana Lopez assigned you “Quarterly plan”",
            time: Date(timeIntervalSince1970: 1_772_451_600),
            actorName: "Ana Lopez"
        ),
        MonarchNotificationCenterItem(
            id: "n2",
            title: "Sam Lee replied to your comment",
            message: "Looks good to me, shipping it after lunch.",
            time: Date(timeIntervalSince1970: 1_772_442_900),
            actorName: "Sam Lee"
        ),
        MonarchNotificationCenterItem(
            id: "n3",
            title: "Your export is ready",
            time: Date(timeIntervalSince1970: 1_772_384_700),
            isRead: true
        ),
    ]

    private var items: [MonarchNotificationCenterItem] {
        source.map {
            MonarchNotificationCenterItem(
                id: $0.id,
                title: $0.title,
                message: $0.message,
                time: $0.time,
                isRead: $0.isRead || read.contains($0.id),
                actorName: $0.actorName
            )
        }
    }

    var body: some View {
        MonarchNotificationsBell(unreadCount: 2) {
            showsNotifications = true
        }
        .sheet(isPresented: $showsNotifications) {
            NavigationStack {
                MonarchNotificationCenter(
                    items,
                    now: Date(timeIntervalSince1970: 1_772_452_800),
                    onMarkRead: { id in read.insert(id) },
                    onMarkAllRead: { read = Set(items.map(\.id)) }
                ) {
                    Button("See all notifications") {}
                        .buttonStyle(.monarchLink(.inline))
                }
            }
            .environment(\.timeZone, .gmt)
        }
    }
}

