/// settings-page: Sections with nav and a danger zone
private struct SettingsPageExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var workspaceName = "Northwind"
    @State private var digest = true

    private func settingsLink(_ title: String, isOpen: Bool, isDanger: Bool) -> some View {
        Button {} label: {
            Text(title)
                .monarchTextStyle(.label)
                .foregroundStyle(isDanger || isOpen ? theme.colors.dangerStrong : theme.colors.textMuted)
                .padding(.horizontal, theme.spacing.space3)
                .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
                .background(isOpen ? theme.colors.dangerSubtle : .clear, in: RoundedRectangle(cornerRadius: theme.radius.md))
        }
        .buttonStyle(.plain)
    }

    private func settingsCard<Content: View>(
        isDanger: Bool = false,
        @ViewBuilder content: () -> Content
    ) -> some View {
        content()
            .padding(theme.spacing.space4)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: theme.radius.lg))
            .overlay(
                RoundedRectangle(cornerRadius: theme.radius.lg).strokeBorder(
                    isDanger ? theme.colors.dangerBorder : theme.colors.borderSubtle,
                    lineWidth: 1
                )
            )
            .overlay(alignment: .leading) {
                if isDanger {
                    Rectangle().fill(theme.colors.dangerStrong).frame(width: 3)
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: theme.radius.lg))
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text("Workspace settings")
                .monarchTextStyle(.title)
                .foregroundStyle(theme.colors.textDefault)
                .accessibilityAddTraits(.isHeader)
            // The section menu beside the open section, as on the web: the open one marked, the danger zone in red.
            HStack(alignment: .top, spacing: theme.spacing.space4) {
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    settingsLink("General", isOpen: true, isDanger: false)
                    settingsLink("Notifications", isOpen: false, isDanger: false)
                    settingsLink("Danger zone", isOpen: false, isDanger: true)
                }
                .frame(width: theme.spacing.space24 + theme.spacing.space8)
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    Text("General").monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.textDefault).accessibilityAddTraits(.isHeader)
                    settingsCard {
                        MonarchTextField("Workspace name", text: $workspaceName)
                    }
                    Text("Notifications").monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.textDefault).accessibilityAddTraits(.isHeader)
                    settingsCard {
                        VStack(alignment: .leading, spacing: theme.spacing.space1) {
                            Text("Email digest").monarchTextStyle(.label).foregroundStyle(theme.colors.textDefault)
                            Text("A summary once a week.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                            Toggle("Email digest", isOn: $digest).labelsHidden()
                        }
                    }
                    Text("Danger zone")
                        .monarchTextStyle(.bodyStrong)
                        .foregroundStyle(theme.colors.dangerStrong)
                        .accessibilityAddTraits(.isHeader)
                    settingsCard(isDanger: true) {
                        VStack(alignment: .leading, spacing: theme.spacing.space2) {
                            Text("Delete this workspace").monarchTextStyle(.label).foregroundStyle(theme.colors.textDefault)
                            Text("Removes the workspace and everything in it.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                            MonarchButton("Delete workspace", variant: .danger, size: .sm) {}
                        }
                    }
                }
            }
        }
    }
}

/// settings-page: On iPad: the list beside the open section
private struct SettingsPageExample1: View {
    @Environment(\.monarchTheme) private var theme
    @State private var selection: String? = "notifications"
    @State private var pending: String?
    @State private var digest = true
    @State private var savedDigest = true
    @State private var isAsking = false

    private let sections = ["profile": "Workspace profile", "notifications": "Notifications", "danger": "Danger zone"]

    private var isDirty: Bool { digest != savedDigest }

    /// Changing section with unsaved changes asks first, on iPad and on iPhone.
    private var guardedSelection: Binding<String?> {
        Binding(
            get: { selection },
            set: { next in
                if isDirty && next != selection {
                    pending = next
                    isAsking = true
                } else {
                    selection = next
                }
            }
        )
    }

    var body: some View {
        NavigationSplitView(
            sidebar: {
                List(selection: guardedSelection) {
                    Section {
                        Label("Workspace profile", systemImage: "building.2").tag("profile")
                        Label("Notifications", systemImage: "bell").tag("notifications")
                    }
                    Section {
                        Label("Danger zone", systemImage: "exclamationmark.triangle")
                            .foregroundStyle(theme.colors.dangerStrong)
                            .tag("danger")
                    }
                }
                .navigationTitle("Settings")
                .navigationSplitViewColumnWidth(min: theme.spacing.space24 * 2, ideal: theme.spacing.space24 * 3)
            },
            detail: {
                Form {
                    if selection == "notifications" {
                        Toggle("Weekly digest", isOn: $digest)
                    } else {
                        Text("Choose a section").foregroundStyle(theme.colors.textMuted)
                    }
                }
                .tint(theme.colors.accentSolid)
                .navigationTitle(sections[selection ?? ""] ?? "Settings")
                .toolbar {
                    ToolbarItem(placement: .confirmationAction) {
                        Button("Save") { savedDigest = digest }
                            .disabled(!isDirty)
                    }
                    .monarchFlat()
                }
                .monarchUnsavedChangesGuard(
                    isPresented: $isAsking,
                    hasChanges: isDirty,
                    onSave: { savedDigest = digest },
                    onLeave: { reason in
                        if reason == .discard { digest = savedDigest }
                        selection = pending
                        pending = nil
                    }
                )
            }
        )
        .frame(minHeight: theme.spacing.space24 * 4)
    }
}

