private struct SplitInboxLayoutExample0: View {
    @Environment(\.monarchTheme) private var theme
    private struct Conversation {
        let subject: String
        let from: String
        let preview: String
    }

    private let conversations = [
        Conversation(subject: "Printer offline on floor 3", from: "Grace Hopper", preview: "It stopped after the update this morning."),
        Conversation(subject: "Invoice shows the wrong address", from: "Alan Turing", preview: "Our billing address changed in March."),
        Conversation(subject: "Reset two-factor", from: "Katherine Johnson", preview: "I replaced my phone and lost the codes."),
    ]
    @State private var selection = 0
    @State private var showsContext = false

    private var list: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                ForEach(Array(conversations.enumerated()), id: \.offset) { index, conversation in
                    Button { selection = index } label: {
                        VStack(alignment: .leading, spacing: theme.spacing.space0_5) {
                            Text(conversation.subject).monarchTextStyle(.label)
                            Text(conversation.from + " \u{00B7} " + conversation.preview)
                                .monarchTextStyle(.caption)
                                .foregroundStyle(theme.colors.textMuted)
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(theme.spacing.space2)
                        .background(
                            selection == index ? theme.colors.accentSubtle : Color.clear,
                            in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                        )
                    }
                    .buttonStyle(.plain)
                    .accessibilityAddTraits(selection == index ? .isSelected : [])
                }
            }
            .padding(theme.spacing.space2)
        }
    }

    private var conversation: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            HStack(alignment: .top, spacing: theme.spacing.space2) {
                Text(conversations[selection].subject).monarchTextStyle(.subheading)
                Spacer(minLength: 0)
                Button { showsContext.toggle() } label: {
                    MonarchIcon(systemName: "rectangle.split.3x1", size: .sm)
                        .foregroundStyle(theme.colors.textDefault)
                }
                .accessibilityLabel(showsContext ? "Hide ticket details" : "Show ticket details")
                .frame(minWidth: 44, minHeight: 44, alignment: .topTrailing)
            }
            MonarchBadge("Open", tone: .info)
            Text("From " + conversations[selection].from)
                .monarchTextStyle(.bodySmall)
                .foregroundStyle(theme.colors.textMuted)
            Text(conversations[selection].preview).monarchTextStyle(.bodySmall)
            if showsContext {
                VStack(alignment: .leading, spacing: theme.spacing.space2) {
                    LabeledContent("Requester", value: conversations[selection].from)
                    LabeledContent("Priority", value: "High")
                    LabeledContent("Assignee", value: "\u{2014}")
                }
                .labeledContentStyle(.monarch)
            }
            Spacer(minLength: 0)
        }
        .padding(theme.spacing.space3)
    }

    var body: some View {
        HStack(spacing: 0) {
            list
                .frame(width: theme.spacing.space24 * 1.7)
            Rectangle().fill(theme.colors.borderSubtle).frame(width: 1)
            conversation
                .frame(maxWidth: .infinity, alignment: .topLeading)
        }
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 12, style: .continuous).stroke(theme.colors.borderSubtle, lineWidth: 1))
        .frame(height: theme.spacing.space24 * 4.4)
    }
}

/// split-inbox-layout: Folders, list and detail
private struct SplitInboxLayoutExample1: View {
    @Environment(\.monarchTheme) private var theme
    @State private var folder: String? = "Open"
    @State private var thread: String?
    private let folders = ["Open", "Pending", "Closed"]

    var body: some View {
        NavigationSplitView(
            sidebar: {
                List(folders, id: \.self, selection: $folder) { name in
                    Text(name).monarchTextStyle(.body)
                }
                .navigationTitle("Support")
            },
            content: {
                List(["Refund request", "Invoice is wrong"], id: \.self, selection: $thread) { name in
                    Text(name).monarchTextStyle(.body)
                }
                .navigationTitle(folder ?? "")
            },
            detail: {
                Text(thread ?? "Choose a conversation")
                    .monarchTextStyle(.body)
                    .foregroundStyle(thread == nil ? theme.colors.textMuted : theme.colors.textDefault)
            }
        )
        .frame(minHeight: theme.spacing.space24 * 3)
    }
}

/// split-layout: Inbox
private struct SplitLayoutExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var selection: String?
    private let items = ["Billing question", "Password reset"]

    var body: some View {
        HStack(spacing: 0) {
            VStack(alignment: .leading, spacing: 0) {
                ForEach(items, id: \.self) { item in
                    Button { selection = item } label: {
                        Text(item).monarchTextStyle(.bodySmall)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(theme.spacing.space3)
                            .background(selection == item ? theme.colors.accentSubtle : Color.clear)
                    }
                    .buttonStyle(.plain)
                    .accessibilityAddTraits(selection == item ? .isSelected : [])
                }
                Spacer(minLength: 0)
            }
            .frame(width: theme.spacing.space24 * 2)
            Rectangle().fill(theme.colors.borderSubtle).frame(width: 1)
            Group {
                if let selection {
                    Text(selection).monarchTextStyle(.bodySmall)
                } else {
                    VStack(spacing: theme.spacing.space2) {
                        Text("No conversation selected").monarchTextStyle(.bodyStrong)
                        Text("Pick one from the list.").monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
                    }
                    .multilineTextAlignment(.center)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
            .padding(.top, theme.spacing.space8)
        }
        .frame(height: theme.spacing.space24 * 3)
    }
}

